#include <stack>
#include <vector>
#include <list>
#include <deque>

// Default (uses std::deque)
std::stack<int> s1;

// Explicitly using std::vector
// Good for high locality, accepts reallocation costs
std::stack<int, std::vector<int>> s2;

// Explicitly using std::list
// Good for guaranteed O(1) push/pop, but higher memory overhead
std::stack<int, std::list<int>> s3;

s1.push(10);
s2.push(20);
